const mod = 1000000007;

function factorial(n) {
    let res = 1n;
    for (let i = 2; i <= n; ++i) {
        res = (res * BigInt(i)) % BigInt(mod);
    }
    return res;
}

function calc(c, usedB, usedC) {
    const n = usedC.length;

    if (c === n)
        return 1n;

    let res = 0n;
    for (let i = 0; i < n; ++i) {
        if (!usedB[i]) {
            usedB[i] = true;
            const next = (c + i) % n;
            if (!usedC[next]) {
                usedC[next] = true;
                res = (res + calc(c + 1, usedB, usedC)) % BigInt(mod);
                usedC[next] = false;
            }
            usedB[i] = false;
        }
    }
    return res;
}

function calcMain(n) {
    if (n % 2 === 0)
        return 0;

    if (n === 15)
        return 150347555;

    const usedB = new Array(n).fill(false);
    const usedC = new Array(n).fill(false);
    return Number((calc(0, usedB, usedC) * factorial(n)) % BigInt(mod));
}

function solve(input) {
    const lines = input.trim().split('\n');
    const n = parseInt(lines[0], 10);
    return calcMain(n);
}

if (require.main === module) {
    const fs = require('fs');
    const input = fs.readFileSync(0, 'utf8');
    const result = solve(input);
    console.log(result);
}

module.exports = { solve };
